// @FIGURE_CODE_BEGIN
(function () {
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';
  container.appendChild(canvas);

  var RED = '#ff3333';
  var AXIS = '#111111';
  var GUIDE = '#555555';
  var PATH = '#1f78b4';
  var SWEEP = '#8e44ad';
  var tripleT = 0.01, tripleP = 0.006, critT = 374, critP = 218;
  var sweepT = -2;
  var currentStep = 0;
  var state = {
    temperature: 25,
    pressure: 1,
    meltingPressure: 1,
    heatingPath: '1 atm path'
  };
  var hitItems = [];

  var steps = [
    {
      title: 'Locate a state point',
      narration: 'The sliders place a black state point on the pressure-temperature diagram. The highlighted region shows that phase is determined by location, not by temperature alone.',
      state: { temperature: 25, pressure: 1, heatingPath: '1 atm path' }
    },
    {
      title: 'Heat at ordinary pressure',
      narration: 'Along the 1 atm path, water crosses the boiling curve near 100°C. The dashed 1 atm and 100°C guides mark the familiar normal boiling point.',
      state: { temperature: 100, pressure: 1, heatingPath: '1 atm path' }
    },
    {
      title: 'Raise pressure near melting',
      narration: 'With temperature held just below 0°C, increasing pressure moves the point upward across the left-leaning melting curve. The phase label changes from solid to liquid, showing why pressure can melt ice.',
      state: { meltingPressure: 150, heatingPath: '1 atm path' }
    },
    {
      title: 'Choose a low-pressure heating path',
      narration: 'At pressures below the triple point, liquid water is not a stable phase. Heating crosses the sublimation boundary, so solid changes directly to vapor.',
      state: { temperature: 0, pressure: 0.003, heatingPath: 'Low-pressure path' }
    },
    {
      title: 'Pass the critical point',
      narration: 'A high-pressure path can go above the critical point instead of crossing a normal boiling boundary. Beyond the critical point, liquid and vapor are no longer separated by a sharp phase boundary.',
      state: { temperature: 400, pressure: 230, heatingPath: 'Supercritical path' }
    }
  ];

  function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

  function interpPiece(v, pts) {
    if (v <= pts[0][0]) return pts[0][1];
    for (var i = 0; i < pts.length - 1; i++) {
      var a = pts[i], b = pts[i + 1];
      if (v <= b[0]) {
        var t = (v - a[0]) / (b[0] - a[0]);
        return a[1] + t * (b[1] - a[1]);
      }
    }
    return pts[pts.length - 1][1];
  }

  function invInterpPiece(n, pts) {
    if (n <= pts[0][1]) return pts[0][0];
    for (var i = 0; i < pts.length - 1; i++) {
      var a = pts[i], b = pts[i + 1];
      if (n <= b[1]) {
        var t = (n - a[1]) / (b[1] - a[1]);
        return a[0] + t * (b[0] - a[0]);
      }
    }
    return pts[pts.length - 1][0];
  }

  var xPts = [[-50, 0], [0, 0.25], [0.01, 0.30], [100, 0.64], [374, 0.86], [450, 1]];
  var yPts = [[0.001, 0], [0.006, 0.31], [1, 0.52], [218, 0.94], [250, 1]];

  function xNorm(T) { return interpPiece(T, xPts); }
  function yNorm(p) { return interpPiece(p, yPts); }

  function plotRect(chart) {
    var w = chart.width, h = chart.height;
    return {
      left: w * 0.17,
      right: w * 0.90,
      top: h * 0.09,
      bottom: h * 0.86,
      width: w * 0.73,
      height: h * 0.77
    };
  }

  function sx(T, r) { return r.left + xNorm(T) * r.width; }
  function sy(p, r) { return r.bottom - yNorm(p) * r.height; }

  function pSub(T) {
    var k = Math.log(tripleP / 0.001) / (tripleT + 50);
    return 0.001 * Math.exp(k * (T + 50));
  }

  function tSubForP(p) {
    var k = Math.log(tripleP / 0.001) / (tripleT + 50);
    return Math.log(p / 0.001) / k - 50;
  }

  function tMelt(p) {
    if (p <= tripleP) return tripleT;
    var u = Math.log(p / tripleP) / Math.log(critP / tripleP);
    return tripleT - 3.0 * Math.pow(clamp(u, 0, 1), 1.18);
  }

  function pMeltForT(T) {
    if (T >= tripleT) return tripleP;
    var u = Math.pow(clamp((tripleT - T) / 3.0, 0, 1), 1 / 1.18);
    return tripleP * Math.exp(u * Math.log(critP / tripleP));
  }

  function lnPBoil(T) {
    var xs = [tripleT, 100, critT];
    var ys = [Math.log(tripleP), Math.log(1), Math.log(critP)];
    var total = 0;
    for (var i = 0; i < 3; i++) {
      var term = ys[i];
      for (var j = 0; j < 3; j++) if (j !== i) term *= (T - xs[j]) / (xs[i] - xs[j]);
      total += term;
    }
    return total;
  }

  function pBoil(T) {
    if (T < tripleT || T > critT) return NaN;
    return Math.exp(lnPBoil(T));
  }

  function tBoilForP(p) {
    if (p < tripleP || p > critP) return NaN;
    var lo = tripleT, hi = critT;
    for (var i = 0; i < 60; i++) {
      var mid = (lo + hi) / 2;
      if (pBoil(mid) < p) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function phaseOf(T, p) {
    if (T > critT && p > critP) return 'supercritical fluid';
    if (p < tripleP) {
      return T < tSubForP(p) ? 'solid' : 'vapor';
    }
    var tm = tMelt(p);
    if (T < tm) return 'solid';
    if (p > critP) return 'liquid';
    var tb = tBoilForP(p);
    if (isFinite(tb) && T > tb) return 'vapor';
    return 'liquid';
  }

  function phaseColor(ph) {
    if (ph === 'solid') return 'rgba(120,160,195,0.20)';
    if (ph === 'liquid') return 'rgba(80,160,230,0.18)';
    if (ph === 'vapor') return 'rgba(245,190,70,0.20)';
    return 'rgba(150,90,200,0.18)';
  }

  function drawLine(ctx, pts, color, width, dash) {
    if (pts.length < 2) return;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.setLineDash(dash || []);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (var i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    ctx.stroke();
    ctx.restore();
  }

  function arrowHead(ctx, x1, y1, x2, y2, size, color) {
    var a = Math.atan2(y2 - y1, x2 - x1);
    ctx.save();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - size * Math.cos(a - Math.PI / 6), y2 - size * Math.sin(a - Math.PI / 6));
    ctx.lineTo(x2 - size * Math.cos(a + Math.PI / 6), y2 - size * Math.sin(a + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawArrowLine(ctx, pts, color, width, dash, head) {
    drawLine(ctx, pts, color, width, dash);
    if (pts.length > 1) {
      var a = pts[pts.length - 2], b = pts[pts.length - 1];
      arrowHead(ctx, a[0], a[1], b[0], b[1], head, color);
    }
  }

  function drawText(ctx, text, x, y, opts) {
    opts = opts || {};
    ctx.save();
    ctx.font = (opts.italic ? 'italic ' : '') + (opts.bold ? 'bold ' : '') + opts.size + 'px sans-serif';
    ctx.textAlign = opts.align || 'center';
    ctx.textBaseline = opts.base || 'middle';
    if (opts.halo !== false) {
      ctx.strokeStyle = 'rgba(255,255,255,0.92)';
      ctx.lineWidth = Math.max(3, opts.size * 0.22);
      ctx.lineJoin = 'round';
      ctx.strokeText(text, x, y);
    }
    ctx.fillStyle = opts.color || '#000';
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function drawH2O(ctx, x, y, size) {
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#000';
    ctx.font = 'bold ' + size + 'px sans-serif';
    var wH = ctx.measureText('H').width;
    var w2 = ctx.measureText('2').width * 0.65;
    var wO = ctx.measureText('O').width;
    var start = x - (wH + w2 + wO) / 2;
    ctx.fillText('H', start + wH / 2, y);
    ctx.font = 'bold ' + Math.round(size * 0.62) + 'px sans-serif';
    ctx.fillText('2', start + wH + w2 / 2, y + size * 0.26);
    ctx.font = 'bold ' + size + 'px sans-serif';
    ctx.fillText('O', start + wH + w2 + wO / 2, y);
    ctx.restore();
  }

  function curvedArrow(ctx, label, x0, y0, cx, cy, x1, y1, tx, ty, fs) {
    ctx.save();
    ctx.strokeStyle = AXIS;
    ctx.lineWidth = Math.max(1.2, fs * 0.10);
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.quadraticCurveTo(cx, cy, x1, y1);
    ctx.stroke();
    var t = 0.96;
    var px = (1 - t) * (1 - t) * x0 + 2 * (1 - t) * t * cx + t * t * x1;
    var py = (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * cy + t * t * y1;
    var qx = (1 - 0.90) * (1 - 0.90) * x0 + 2 * (1 - 0.90) * 0.90 * cx + 0.90 * 0.90 * x1;
    var qy = (1 - 0.90) * (1 - 0.90) * y0 + 2 * (1 - 0.90) * 0.90 * cy + 0.90 * 0.90 * y1;
    arrowHead(ctx, qx, qy, px, py, fs * 0.62, AXIS);
    ctx.restore();
    drawText(ctx, label, tx, ty, { size: fs, align: tx < x0 ? 'right' : 'left', halo: true });
    hitItems.push({ x: tx, y: ty, r: fs * 4, label: label + ' boundary', popup: label });
  }

  function addHit(x, y, r, label, popup) {
    hitItems.push({ x: x, y: y, r: r, label: label, popup: popup });
  }

  function drawPhaseHighlight(ctx, r) {
    var ph = phaseOf(state.temperature, state.pressure);
    ctx.save();
    ctx.fillStyle = phaseColor(ph);
    ctx.beginPath();
    if (ph === 'solid') {
      ctx.moveTo(sx(-50, r), sy(250, r));
      for (var p = 250; p >= tripleP; p -= 5) ctx.lineTo(sx(tMelt(p), r), sy(p, r));
      for (var T = tripleT; T >= -50; T -= 1) ctx.lineTo(sx(T, r), sy(pSub(T), r));
      ctx.lineTo(sx(-50, r), sy(0.001, r));
      ctx.closePath();
    } else if (ph === 'liquid') {
      ctx.moveTo(sx(tMelt(250), r), sy(250, r));
      for (var p2 = 250; p2 >= tripleP; p2 -= 4) ctx.lineTo(sx(tMelt(p2), r), sy(p2, r));
      for (var T2 = tripleT; T2 <= critT; T2 += 5) ctx.lineTo(sx(T2, r), sy(pBoil(T2), r));
      ctx.lineTo(sx(critT, r), sy(250, r));
      ctx.closePath();
    } else if (ph === 'vapor') {
      ctx.moveTo(sx(-50, r), sy(0.001, r));
      ctx.lineTo(sx(450, r), sy(0.001, r));
      ctx.lineTo(sx(450, r), sy(critP, r));
      for (var T3 = critT; T3 >= tripleT; T3 -= 5) ctx.lineTo(sx(T3, r), sy(pBoil(T3), r));
      for (var T4 = tripleT; T4 >= -50; T4 -= 1) ctx.lineTo(sx(T4, r), sy(pSub(T4), r));
