    ctx.fill();
    ctx.restore();
  }

  function drawPath(ctx, r, fs) {
    var p, pts = [], label = '', lx = 0, ly = 0;
    if (state.heatingPath === '1 atm path') {
      p = 1;
      for (var T = -50; T <= 170; T += 4) pts.push([sx(T, r), sy(p, r)]);
      label = 'boiling'; lx = sx(108, r); ly = sy(1, r) - fs * 1.15;
    } else if (state.heatingPath === 'Low-pressure path') {
      p = 0.003;
      for (var T2 = -50; T2 <= 120; T2 += 4) pts.push([sx(T2, r), sy(p, r)]);
