    }
    drawArrowLine(ctx, pts, PATH, Math.max(2, fs * 0.16), [], fs * 0.7);
    drawText(ctx, label, lx, ly, { size: fs * 0.85, color: PATH, bold: true, halo: true });
    addHit(lx, ly, fs * 5, 'Heating path: ' + state.heatingPath, 'Heating path');
  }

  var phasePlugin = {
    id: 'phaseDiagram',
    beforeDraw: function (chart) {
      var ctx = chart.ctx;
      var r = plotRect(chart);
      var minD = Math.min(r.width, r.height);
      var fs = clamp(minD * 0.045, 10, 18);
      var small = clamp(minD * 0.038, 9, 15);
      var lw = clamp(minD * 0.006, 1.4, 2.5);
      hitItems = [];

      ctx.clearRect(0, 0, chart.width, chart.height);
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, chart.width, chart.height);

      drawPhaseHighlight(ctx, r);

      ctx.save();
      ctx.strokeStyle = AXIS;
      ctx.lineWidth = Math.max(1.2, lw * 0.75);
      ctx.beginPath();
      ctx.moveTo(r.left, r.bottom);
      ctx.lineTo(r.right + fs * 0.8, r.bottom);
      ctx.moveTo(r.left, r.bottom);
      ctx.lineTo(r.left, r.top - fs * 0.35);
      ctx.stroke();
      arrowHead(ctx, r.right, r.bottom, r.right + fs * 0.8, r.bottom, fs * 0.55, AXIS);
      arrowHead(ctx, r.left, r.top + fs * 0.6, r.left, r.top - fs * 0.35, fs * 0.55, AXIS);
      ctx.restore();

      function guideH(p, xEnd) {
        drawLine(ctx, [[r.left, sy(p, r)], [xEnd, sy(p, r)]], GUIDE, Math.max(1, lw * 0.55), [fs * 0.45, fs * 0.28]);
      }
      function guideV(T, yEnd) {
        drawLine(ctx, [[sx(T, r), r.bottom], [sx(T, r), yEnd]], GUIDE, Math.max(1, lw * 0.55), [fs * 0.45, fs * 0.28]);
      }

      guideH(tripleP, sx(tripleT, r));
      guideV(tripleT, sy(tripleP, r));
      guideH(1, sx(100, r));
      guideV(100, sy(1, r));
      guideH(critP, sx(critT, r));
      guideV(critT, sy(critP, r));

      var sub = [];
      for (var Ts = -50; Ts <= tripleT; Ts += 1) sub.push([sx(Ts, r), sy(pSub(Ts), r)]);
      var melt = [];
      for (var pm = tripleP; pm <= 230; pm *= 1.12) melt.push([sx(tMelt(pm), r), sy(pm, r)]);
      melt.push([sx(tMelt(250), r), sy(250, r)]);
      var boil = [];
      for (var Tb = tripleT; Tb <= critT; Tb += 4) boil.push([sx(Tb, r), sy(pBoil(Tb), r)]);
      drawLine(ctx, sub, RED, lw, []);
      drawLine(ctx, melt, RED, lw, []);
      drawLine(ctx, boil, RED, lw, []);

      drawPath(ctx, r, fs);

      var sweepPts = [[sx(sweepT, r), sy(0.006, r)], [sx(sweepT, r), sy(state.meltingPressure, r)]];
      drawArrowLine(ctx, sweepPts, SWEEP, Math.max(1.5, lw * 0.9), [fs * 0.25, fs * 0.25], fs * 0.52);
      ctx.save();
      ctx.fillStyle = SWEEP;
      ctx.beginPath();
      ctx.arc(sx(sweepT, r), sy(state.meltingPressure, r), fs * 0.34, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      addHit(sx(sweepT, r), sy(state.meltingPressure, r), fs, 'Pressure sweep near the melting line', 'Pressure can melt ice');

      var tx = sx(tripleT, r), ty = sy(tripleP, r);
      var cx = sx(critT, r), cy = sy(critP, r);
      ctx.save();
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.arc(tx, ty, fs * 0.32, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(cx, cy, fs * 0.32, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
      addHit(tx, ty, fs, 'Triple point: solid, liquid, and vapor meet', 'Triple point');
      addHit(cx, cy, fs, 'Critical point: liquid-vapor boundary ends', 'Critical point');

      var spx = sx(state.temperature, r), spy = sy(state.pressure, r);
      ctx.save();
      ctx.fillStyle = '#111';
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = Math.max(2, fs * 0.18);
      ctx.beginPath();
      ctx.arc(spx, spy, fs * 0.42, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
      addHit(spx, spy, fs * 1.2, 'State point: ' + phaseOf(state.temperature, state.pressure), 'State point');

      drawText(ctx, 'Triple\npoint', tx + fs * 0.65, ty + fs * 1.2, { size: fs, align: 'left', base: 'middle', halo: true });
      drawText(ctx, 'Critical point', cx, cy - fs * 1.35, { size: fs, align: 'center', halo: true });

      drawText(ctx, 's', sx(-12, r), sy(0.035, r), { size: fs * 1.1, italic: true, halo: true });
      drawText(ctx, 'l', sx(28, r), sy(20, r), { size: fs * 1.1, italic: true, halo: true });
